  "target_rule_id": "R02",
  "principle": {
    "instruction": "Link a modifier to the word it describes, indicating a qualifying relationship.",
    "applies_when": "Two entities form a modifier–head pair (e.g., adjective–noun, attributive noun–noun). The subject is typically the modifier (e.g., 'large', 'mild', 'right') and the object is the head (e.g., 'effusion', 'changes', 'hilum'). When both entities are ANAT, predict Modify only if the subject is a directional/laterality term (e.g., 'right', 'left', 'upper', 'lower', 'ascending', 'descending', 'anterior', 'posterior', 'medial', 'lateral', 'proximal', 'distal') or the object is a recognized structural feature (e.g., 'vasculature', 'structures').",
    "exceptions": [
      "Do not apply if the subject is an observation (label starts with 'OBS-') and a linking verb (is, are, was, were, appears, remains, etc.) intervenes between the subject and object, indicating predicative usage rather than attributive modification."
    ],
    "priority": 2,
    "examples": [
      "mild Modify changes",
      "large Modify effusion",
      "right Modify hilum",
      "ascending Modify aorta",
      "pulmonary Modify vasculature"
    ]
  },
  "rationale": "The current R02 allows any modifier-head pair, leading to spurious edges where compound noun phrases are split (e.g., 'thoracic spine', 'cardiac silhouette') and where predicative adjectives are linked (e.g., 'unremarkable ... silhouette'). By restricting ANAT-ANAT pairs to directional/structural cases and forbidding predicative observations, we reduce false positives while retaining the core modifier-head relations."
}

